import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int T = Integer.parseInt(line.trim());while (T-- > 0) {String line2 = br.readLine();while (line2 != null && line2.trim().isEmpty()) line2 = br.readLine();if (line2 == null) break;StringTokenizer st = new StringTokenizer(line2);int N = Integer.parseInt(st.nextToken());int M = Integer.parseInt(st.nextToken());int[][] grid = new int[N][M];for (int i = 0; i < N; i++) {st = new StringTokenizer(br.readLine());for (int j = 0; j < M; j++) {grid[i][j] = Integer.parseInt(st.nextToken());}}int troopCount = 0;int maxTroopSize = 0;for (int i = 0; i < N; i++) {for (int j = 0; j < M; j++) {if (grid[i][j] == 1) {troopCount++;int currentSize = dfs(grid, i, j, N, M);if (currentSize > maxTroopSize) {maxTroopSize = currentSize;}}}}System.out.println(troopCount + " " + maxTroopSize);}}private static int dfs(int[][] grid, int r, int c, int N, int M) {if (r < 0 || r >= N || c < 0 || c >= M || grid[r][c] == 0) {return 0;}grid[r][c] = 0;int count = 1;for (int dr = -1; dr <= 1; dr++) {for (int dc = -1; dc <= 1; dc++) {if (dr == 0 && dc == 0) continue;count += dfs(grid, r + dr, c + dc, N, M);}}return count;}}